init(eqm,
     #role{lev = 1, classes = Classes,
           p_eqm = Peqm = #package{items = []}}) ->
    DataList = case eqm_data:get_init(Classes) of
                   L = [_ | _] -> L;
                   _ -> []
               end,
    Items = do_init(DataList),
    Peqm#package{items = Items};
init(eqm, #role{p_eqm = Peqm}) -> Peqm;
init(bag, #role{p_bag = Pbag}) -> Pbag.

login(Role) ->
    {ok, Role1} = repair_eqm_repetition_hole(Role),
    {ok, Role2} = repair_hero_stone(Role1),
    Role3 = calc_all_enchant(Role2, 0),
    Role3.

coin_back_flag(Peqm = #package{items = Items}) ->
    Items1 = do_coin_back_flag(Items, []),
    Peqm#package{items = Items1};
coin_back_flag(Peqm) -> Peqm.

do_coin_back_flag([], Items) -> lists:reverse(Items);
do_coin_back_flag([Eqm = #item{lev = Lev, data = Data}
                   | T],
                  Items) ->
    CoinVal = coin_back_val(Lev),
    NewEqm = case CoinVal > 0 of
                 true -> Eqm#item{data = [{5, CoinVal} | Data]};
                 _ -> Eqm
             end,
    do_coin_back_flag(T, [NewEqm | Items]).

hero_stone_flag(Peqm = #package{items = Items},
                #m_var{other_vars = OtherVar}) ->
    Now = date:unixtime(),
    TimeCheck = case lists:keyfind(2046, 1, OtherVar) of
                    {_, LastTime} ->
                        case Now - LastTime >= 15 * 86400 of
                            true -> true;
                            _ -> false
                        end;
                    _ -> true
                end,
    case TimeCheck of
        true ->
            Items1 = do_hero_stone_flag(Items, []),
            Peqm#package{items = Items1};
        _ -> Peqm
    end;
hero_stone_flag(Peqm, _) -> Peqm.

do_hero_stone_flag([], Items) -> lists:reverse(Items);
do_hero_stone_flag([Eqm = #item{lev = Lev, attr = Attr,
                                extra = Extra}
                    | T],
                   Items) ->
    case Lev >= 90 of
        true ->
            case lists:keyfind(112, #attr_base.name, Attr) of
                #attr_base{val = Stone} ->
                    case blacksmith_data:get_stone(Stone) of
                        #{lev := StoneLev} when StoneLev >= 6 ->
                            NewExtra = lists:keystore(24,
                                                      1,
                                                      Extra,
                                                      {24, 1, ""}),
                            NewEqm = Eqm#item{extra = NewExtra},
                            do_hero_stone_flag(T, [NewEqm | Items]);
                        _ -> do_hero_stone_flag(T, [Eqm | Items])
                    end;
                _ -> do_hero_stone_flag(T, [Eqm | Items])
            end;
        _ -> do_hero_stone_flag(T, [Eqm | Items])
    end.

calc_all_enchant(Role = #role{p_eqm =
                                  #package{items = Eqm}},
                 Push) ->
    case eqm_attr:get_all_enchant(Eqm, 1000, 0) of
        false ->
            NewRole = skill_prac:upgrade(Role, 2, [], Push),
            NewRole;
        {ok, _, SkillPrac, _} ->
            NewRole = skill_prac:upgrade(Role, 2, SkillPrac, Push),
            NewRole
    end.

calc_comprehend_craft_num(#role{p_eqm =
                                    #package{items = Items}},
                          CraftLev) ->
    Fun = fun (#item{attr = Attr}) ->
                  case [A
                        || A = #attr_base{type = 5, flag = CraftLev1} <- Attr,
                           CraftLev =:= CraftLev1]
                      of
                      [_ | _] -> true;
                      _ -> false
                  end
          end,
    length([I || I <- Items, Fun(I)]).

calc_all_stone_lev(#role{p_eqm =
                             #package{items = Items}}) ->
    AttrList = lists:append([Attr
                             || #item{attr = Attr} <- Items]),
    Fun = fun (#attr_base{type = 3, val = Val}, CountLev)
                  when Val > 0 ->
                  case blacksmith_data:get_stone(Val) of
                      #{lev := Lev} -> CountLev + Lev;
                      _ -> CountLev
                  end;
              (_, CountLev) -> CountLev
          end,
    lists:foldl(Fun, 0, AttrList).

use_eqm(Item = #item{id = Id, type = Type,
                     lev = ItemLev},
        _BaseItem, _Num, Role = #role{p_eqm = Peqm}) ->
    case is_eqm(Type) of
        false -> {false, lang:get("该道具不可穿戴")};
        true ->
            case package:find(by_id, type_to_id(Type), Peqm) of
                false ->
                    Loss = [#loss{label = item_id, val = [{Id, 1}],
                                  msg = lang:get("装备不存在，无法使用")}],
                    case role_gain:do(Loss, Role) of
                        {false, L} -> {false, L#loss.msg};
                        {ok, NewRole} ->
                            NewId = type_to_id(Type),
                            NewPos = type_to_pos(Type),
                            PutItem = Item#item{id = NewId, pos = NewPos},
                            case package:add(by_items, eqm, NewRole, [PutItem])
                                of
                                {ok, NewEqm} ->
                                    {ok, NewRole#role{p_eqm = NewEqm}};
                                _ -> {false, lang:get("穿戴装备失败")}
                            end
                    end;
                {ok, #item{lev = EqmLev}} when EqmLev >= ItemLev ->
                    LossAndGain = [#loss{label = item_id, val = [{Id, 1}]},
                                   #gain{label = coin, val = 1000}],
                    case role_gain:do(LossAndGain, Role) of
                        {false, _} -> {false, lang:get("装备不存在, 无法使用")};
                        {ok, NewRole} ->
                            notice:send(NewRole,
                                        1,
                                        lang:get("您已经穿戴了更高级装备, 自动转换成1000银币")),
                            {ok, NewRole}
                    end;
                {ok, OffItem = #item{}} ->
                    {ok, NewRole} = check_change(Item, OffItem, Role),
                    {ok, NewRole}
            end
    end.

gm_add_skill(Role = #role{p_eqm =
                              Peqm = #package{items = EqmList}},
             Type, SkillName, SkillId) ->
    case lists:keyfind(Type, #item.type, EqmList) of
        Eqm = #item{id = EqmId, attr = Attrs} ->
            {_, RestAttrs} = lists:partition(fun (#attr_base{type =
                                                                 BType}) ->
                                                     BType =:= 4
                                             end,
                                             Attrs),
            AttrBase = #attr_base{type = 4, name = SkillName,
                                  val = SkillId},
            NewAttrs = [AttrBase | RestAttrs],
            NewEqm = eqm_attr:calc_eqm(Eqm#item{attr = NewAttrs}),
            NewEqmList = lists:keystore(EqmId,
                                        #item.id,
                                        EqmList,
                                        NewEqm),
            NewPeqm = Peqm#package{items = NewEqmList},
            NewRole = Role#role{p_eqm = NewPeqm},
            role:link_send(NewRole, 10302, {NewEqmList}),
            {ok, NewRole};
        _ ->
            logger:info("找不到[~w]类型的装备", [Type], eqm, 251),
            ok
    end.

gm_reset(Role = #role{name = RoleName,
                      p_eqm = Peqm = #package{items = EqmList}}) ->
    {BackStone, NewEqmList} = do_gm_reset(Role,
                                          EqmList,
                                          [],
                                          []),
    NewPeqm = Peqm#package{items = NewEqmList},
    NewRole = Role#role{p_eqm = NewPeqm},
    NewRole1 = attr:calc_and_push(NewRole),
    logger:info("给[~ts]进行装备检测,邮件发送[~w]",
                [RoleName, BackStone],
                eqm,
                264),
    role:link_send(Role, 10302, {NewEqmList}),
    Title = lang:get("装备错乱宝石返还"),
    Content = case BackStone of
                  [_ | _] ->
                      lang:get("由于您在最近装备锻造过程中发生错误，导致您的装备数据异常，现已为您修复正常，异常的宝石已转"
                               "换金币返还给您。请留意您的装备数据，如有其他任何问题请联系QQ 100047886。");
                  _ ->
                      lang:get("由于您在最近装备锻造过程中发生错误，导致您的装备数据异常，现已为您修复正常，请留意您的装备"
                               "数据，如有其他任何问题请联系QQ 100047886。")
              end,
    mail:send(Role,
              #{title => Title, content => Content,
                items => BackStone}),
    {ok, NewRole1}.

do_gm_reset(_Role, [], EqmList, BackStone) ->
    {BackStone, EqmList};
do_gm_reset(Role = #role{classes = Classes},
            [Eqm = #item{id = Id, type = Type, lev = EqmLev} | T],
            EqmList, BackStone) ->
    RealType = id_to_type(Id, Classes),
    case RealType =:= Type of
        true ->
            do_gm_reset(Role, T, [Eqm | EqmList], BackStone);
        false ->
            case eqm_data:get_eqm_id({Classes, RealType, EqmLev}) of
                NewBaseId
                    when is_integer(NewBaseId) andalso NewBaseId > 0 ->
                    case gm_reset_eqm(Role, Eqm, NewBaseId) of
                        {true, AddBackStone, NewEqm} ->
                            do_gm_reset(Role,
                                        T,
                                        [NewEqm | EqmList],
                                        AddBackStone ++ BackStone);
                        _ -> do_gm_reset(Role, T, [Eqm | EqmList], BackStone)
                    end;
                _ ->
                    logger:error("无法找到[~w,~w,~w]对应的装备",
                                 [Classes, RealType, EqmLev],
                                 eqm,
                                 294),
                    do_gm_reset(Role, T, [Eqm | EqmList], BackStone)
            end
    end.

gm_reset_eqm(_Role, OldEqm = #item{attr = Attrs},
             NewBaseId) ->
    case item_data:get(NewBaseId) of
        #item_base{look_id = LookId, type = EqmType,
                   classes = Classes, lev = EqmLev} ->
            NewEqm = OldEqm#item{base_id = NewBaseId,
                                 look_id = LookId, type = EqmType,
                                 classes = Classes},
            NewAttrs = gm_reset_eqm_attr(Classes,
                                         EqmType,
                                         EqmLev,
                                         Attrs),
            {BackStone, NewAttrs1} =
                gm_reset_check_eqm_hole(NewAttrs, EqmType, [], []),
            NewEqm1 = eqm_attr:calc_eqm(NewEqm#item{attr =
                                                        NewAttrs1}),
            {true, BackStone, NewEqm1};
        _ ->
            logger:error("无法找到[~w]装备", [NewBaseId], eqm, 309),
            false
    end.

gm_reset_check_eqm_hole([], _EqmType, BackStone,
                        NewAttrs) ->
    {BackStone, NewAttrs};
gm_reset_check_eqm_hole([Attr = #attr_base{name =
                                               HoleName,
                                           val = HoleBaseId}
                         | T],
                        EqmType, BackStone, NewAttrs)
    when HoleName =:= 110 orelse HoleName =:= 111 ->
    case blacksmith:stone_info(HoleBaseId) of
        #{type := StoneType, lev := StoneLev} ->
            List = blacksmith_data:get_embed(EqmType),
            case lists:keyfind(StoneType, 1, List) of
                false ->
                    case blacksmith_data:remove_stone(HoleBaseId) of
                        #{base_id := BackBaseId} ->
                            Count = round(math:pow(2, StoneLev)) - 1,
                            case market_gold:query_market_price(BackBaseId) of
                                {ok, #market_price{price = StonePrice}} ->
                                    AllPrice = round(Count * StonePrice),
                                    Back = {90003, AllPrice},
                                    logger:info("返还[~w]个[~w],单价[~w],累计[~w]",
                                                [Count,
                                                 BackBaseId,
                                                 StonePrice,
                                                 AllPrice],
                                                eqm,
                                                328),
                                    gm_reset_check_eqm_hole(T,
                                                            EqmType,
                                                            [Back | BackStone],
                                                            NewAttrs);
                                _Err ->
                                    logger:error("无法获取[~w]的价格",
                                                 [BackBaseId],
                                                 eqm,
                                                 331),
                                    gm_reset_check_eqm_hole(T,
                                                            EqmType,
                                                            BackStone,
                                                            [Attr | NewAttrs])
                            end;
                        _ ->
                            logger:error("找不到[~w]的基础宝石信息",
                                         [HoleBaseId],
                                         eqm,
                                         335),
                            gm_reset_check_eqm_hole(T,
                                                    EqmType,
                                                    BackStone,
                                                    [Attr | NewAttrs])
                    end;
                _ ->
                    gm_reset_check_eqm_hole(T,
                                            EqmType,
                                            BackStone,
                                            [Attr | NewAttrs])
            end;
        _ ->
            logger:error("找不到[~w]的宝石信息", [HoleBaseId], eqm, 342),
            gm_reset_check_eqm_hole(T,
                                    EqmType,
                                    BackStone,
                                    [Attr | NewAttrs])
    end;
gm_reset_check_eqm_hole([#attr_base{name = 112,
                                    flag = Flag, val = HoleBaseId}
                         | T],
                        EqmType, BackStone, NewAttrs) ->
    Count = Flag div 5 +
                eqm_data:get_hole_reply_count(HoleBaseId),
    Back = {21098, 1, Count},
    gm_reset_check_eqm_hole(T,
                            EqmType,
                            [Back | BackStone],
                            NewAttrs);
gm_reset_check_eqm_hole([Attr | T], EqmType, BackStone,
                        NewAttrs) ->
    gm_reset_check_eqm_hole(T,
                            EqmType,
                            BackStone,
                            [Attr | NewAttrs]).

gm_reset_eqm_attr(_Classes, EqmType, EqmLev, Attrs) ->
    Fun = fun (#attr_base{type = 0, flag = Step},
               MaxStep) ->
                  max(Step, MaxStep);
              (_, MaxStep) -> MaxStep
          end,
    GetMaxStep = lists:foldl(Fun, 1, Attrs),
    NewBaseAttr = eqm_attr:get_base_attr(EqmType,
                                         EqmLev,
                                         GetMaxStep),
    {_, RestAttr} = lists:partition(fun (#attr_base{type =
                                                        AType}) ->
                                            AType =:= 0
                                    end,
                                    Attrs),
    NewAttrs = NewBaseAttr ++ RestAttr,
    {SpecialSkill, RestAttr2} = lists:partition(fun
                                                    (#attr_base{type =
                                                                    BType}) ->
                                                        BType =:= 4
                                                end,
                                                NewAttrs),
    logger:info("重新计算[~w]装备星数为[~w],并剔除特效[~w]",
                [EqmType, GetMaxStep, SpecialSkill],
                eqm,
                365),
    RestAttr2.

